from checks import available
def reserve(stock, requests):
    new_requests = {}
    for sku, quantity in requests:
        if quantity <= 0: raise ValueError('nonpositive quantity')
        if not available(stock, sku, quantity): raise ValueError('unavailable')
        new_requests[sku] = new_requests.get(sku, 0) + quantity
    updated_stock = stock.copy()
    for sku, quantity in new_requests.items():
        if updated_stock[sku] < quantity: raise ValueError('insufficient stock')
        updated_stock[sku] -= quantity
    return updated_stock

